/* ---------- Khuyến mãi mỗi ngày (giống nhau cho cả hai vì dựa vào ngày) ---------- */
function rng(seed) { let a = seed >>> 0; return () => { a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296 } }
export const ALL = Object.entries(PROD).flatMap(([k, list]) => list.map(p => ({ k, e: p[0], n: p[1], p: p[2], tag: p[3] || '' })));
export function dealsToday(d = new Date()) {
  const r = rng(d.getFullYear() * 10000 + (d.getMonth() + 1) * 100 + d.getDate()); const pool = ALL.slice(); const out = {};
  for (let i = 0; i < 14 && pool.length; i++) { const it = pool.splice(Math.floor(r() * pool.length), 1)[0]; out[it.n] = i % 4 === 3 ? { b2g1: true } : { pct: [10, 15, 20, 25, 30, 40, 50][Math.floor(r() * 7)] } }
  return out;
}
// quầy ăn thử: mỗi ngày 3 món khác nhau
export function samplesToday(d = new Date()) {
  const r = rng(d.getFullYear() * 1000 + d.getMonth() * 40 + d.getDate() + 7); const pool = ['deli', 'frozen', 'bakery', 'junk', 'snacks', 'fruit', 'north', 'central', 'south', 'street'].flatMap(k => PROD[k].map(p => ({ k, e: p[0], n: p[1], p: p[2] })));
  const out = []; for (let i = 0; i < 3; i++)out.push(pool.splice(Math.floor(r() * pool.length), 1)[0]); return out;
}
